import{_ as p,a0 as u,w as a,s as o,ao as r,I as n,x as i,a1 as s,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"现代 Linux 的五大初始化系统（1992-2015） | LCTT x X-CMD","titleTemplate":false,"description":"现代 Linux 的五大初始化系统（1992-2015） | LCTT (201610) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"现代 Linux 的五大初始化系统（1992-2015） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"现代 Linux 的五大初始化系统（1992-2015） | LCTT (201610) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201610/20160811 5 best linux init system","title":"现代 Linux 的五大初始化系统（1992-2015）","tag":"201610","desc":""},"relativePath":"201610/20160811 5 best linux init system.md","filePath":"[post].md"}'),m={name:"201610/20160811 5 best linux init system.md"};function d(x,t,S,T,y,f){const l=u("Link");return a(),o("div",null,[t[21]||(t[21]=r('<h1 id="现代-linux-的五大初始化系统-1992-2015" tabindex="-1">现代 Linux 的五大初始化系统（1992-2015） <a class="header-anchor" href="#现代-linux-的五大初始化系统-1992-2015" aria-label="Permalink to “现代 Linux 的五大初始化系统（1992-2015）”">​</a></h1><p>在 Linux 和其他类 Uniux 系统中，init（初始化）进程是系统启动时由内核执行的第一个进程，其进程 ID（PID）为 1，并静默运行在后台，直到系统关闭。</p><p>init 进程负责启动其他所有的进程，比如守护进程、服务和其他后台进程，因此，它是系统中其它所有进程之母（偏偏叫做“父进程”）。某个进程可以启动许多个子进程，但在这个过程中，某个子进程的父进程结束之后，该子进程的父进程会变成 init 进程。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/08/Linux-init-Systems.png" alt=""></p><p>这么多年过去了，许多的初始化系统在主流 Linux 脱颖而出，和本文中，我将你来看看在 Linux 操作系统最好的初始化系统。</p><h3 id="_1-system-v-init" tabindex="-1">1. System V Init <a class="header-anchor" href="#_1-system-v-init" aria-label="Permalink to “1. System V Init”">​</a></h3><p>System V (SysV) 是一个在类 Unix 系统中最为成熟而且大受欢迎的初始化方案，是 Unix/Linux 系统中所有进程的父进程。SysV 是第一个商业 Unix 系统设计的初始化方案。</p><p>除了 Gentoo 使用自主的初始化系统、Slackware 使用 BSD 风格的初始化方案外，几乎所有的 Linux 发行版都率先使用 SysV 作为初始化方案。</p><p>随着时间的推移，由于一些设计上的缺陷，有几个 SysV 初始化替换方案已经开发出来，用以为 Linux 创建更加高效和完美的初始化系统。</p><p>尽管这些替代方案都超越了 SysV 并提供了更多新特性，但它们仍然和原始 SysV 初始化脚本保持兼容。</p><h3 id="_2-systemd" tabindex="-1">2. SystemD <a class="header-anchor" href="#_2-systemd" aria-label="Permalink to “2. SystemD”">​</a></h3><p>SystemD 是一个 Linux 平台中相对较新的初始化方案。它由 Fedora 15 引入，集成了各类工具以便更好的管理系统。主要目的是：系统初始化、管理和跟踪引导进程中和系统运行时所有的系统进程。</p><p>Systemd 全面有别于其他传统的 Unix 初始化系统，特别是在启动系统和服务管理方面。它同样兼容 SysV 和 LBS 初始化脚本。</p><p>其中较为突出的特性如下：</p><ul><li>纯粹、简单、高效的设计</li><li>启动时的并发和并行处理</li><li>更好的 API</li><li>开启可选进程的移除功能</li><li>使用 journald 来支持事件日志</li><li>使用 systemd calender timers 来支持任务计划</li><li>以二进制文件存储日志</li><li>保存 systemd 的状态以待今后查看</li><li>与 GNOME 更好整合实现等</li></ul>',15)),n("p",null,[t[1]||(t[1]=i("查看 Systemd 初始化系统简介：",-1)),s(l,{href:"https://fedoraproject.org/wiki/Systemd"},{default:e(()=>[...t[0]||(t[0]=[i("https://fedoraproject.org/wiki/Systemd",-1)])]),_:1})]),t[22]||(t[22]=r('<h3 id="_3-upstart" tabindex="-1">3. Upstart <a class="header-anchor" href="#_3-upstart" aria-label="Permalink to “3. Upstart”">​</a></h3><p>Upstart 是一个基于事件的初始化系统，由 Ubuntu 的制作团队开发的，用以替代 SysV。它可以启动不同的系统任务和进程、在系统运行时校验进程并在系统关闭时结束进程。</p><p>它是一个使用 SysV 和 Systemd 启动脚本的混合初始化系统，Upstart 中值得一提的特性如下：</p><ul><li>Ubuntu 的原生初始化系统，但可以运行在其他所有的发行版中</li><li>基于事件启动/结束的任务和服务</li><li>启动/结束任务和服务时生成事件</li><li>可以由其他系统进程发送事件</li><li>使用 D-Bus 和 init 进程通信</li><li>用户可以启动/结束其各自的进程</li><li>可以再现崩溃的进程等</li></ul>',4)),n("p",null,[t[3]||(t[3]=i("访问 Upstart 主页：",-1)),s(l,{href:"http://upstart.ubuntu.com/index.html"},{default:e(()=>[...t[2]||(t[2]=[i("http://upstart.ubuntu.com/index.html",-1)])]),_:1})]),t[23]||(t[23]=r('<h3 id="_4-openrc" tabindex="-1">4. OpenRC <a class="header-anchor" href="#_4-openrc" aria-label="Permalink to “4. OpenRC”">​</a></h3><p>OpenRC 是一个基于依赖关系的类 Unix 系统初始化方案，兼容 SysV。基本可以说是 SysV 的升级版，但必须要清楚记住的是：OpenRC 并非只是完全替代 /sbin/init 文件。</p><p>它所提供的出色特性如下：</p><ul><li>可运行在包括 Gentoo 和 BSD 在内的多数 Linux 系统之中</li><li>支持硬件触发的初始化脚本（LCTT 译注：如硬件热插拔所触发的）</li><li>支持单个配置文件</li><li>不支持单个服务配置文件</li><li>以守护进程的方式运行</li><li>并行服务启动等</li></ul>',4)),n("p",null,[t[5]||(t[5]=i("访问 OpenRC 主页：",-1)),s(l,{href:"https://wiki.gentoo.org/wiki/OpenRC"},{default:e(()=>[...t[4]||(t[4]=[i("https://wiki.gentoo.org/wiki/OpenRC",-1)])]),_:1})]),t[24]||(t[24]=r('<h3 id="_5-runit" tabindex="-1">5. runit <a class="header-anchor" href="#_5-runit" aria-label="Permalink to “5. runit”">​</a></h3><p>runit 同样是一个跨平台初始化系统，可以运行在 GNU/Linux、Solaris、BSD 和 Mac OS X 中，用替代 SysV，同时提供服务监控。</p><p>相比于 SysV 和其他 Linux 初始化系统，它提供了一些好用和卓越的组件，如下：</p><ul><li>服务监控：每个服务都关联一个服务目录</li><li>清理进程状态，以保证每个进程处于干净状态</li><li>可靠的日志机制</li><li>快速的系统启动和关闭</li><li>可移植</li><li>打包方便</li><li>代码体积小等</li></ul>',4)),n("p",null,[t[7]||(t[7]=i("访问 runit 主页：",-1)),s(l,{href:"http://smarden.org/runit/"},{default:e(()=>[...t[6]||(t[6]=[i("http://smarden.org/runit/",-1)])]),_:1})]),t[25]||(t[25]=n("p",null,"正如我之前所说的，Linux 中的初始化系统负责启动和管理所有的进程。此外，SysV 是 Linux 系统中主要的初始化系统，但由于一些性能缺陷，系统开发者已经开发出几个替代品。",-1)),t[26]||(t[26]=n("p",null,"在这里，我已经介绍了几个可用的替代方案，但你可能觉得有一些其他的初始化系统值得在此提及。请在下方的评论区将你的想法告诉我们。",-1)),t[27]||(t[27]=n("hr",null,null,-1)),n("p",null,[t[9]||(t[9]=i("via: ",-1)),s(l,{href:"http://www.tecmint.com/best-linux-init-systems/"},{default:e(()=>[...t[8]||(t[8]=[i("http://www.tecmint.com/best-linux-init-systems/",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=i("作者：",-1)),s(l,{href:"http://www.tecmint.com/author/aaronkili/"},{default:e(()=>[...t[10]||(t[10]=[i("Aaron Kili",-1)])]),_:1}),t[14]||(t[14]=i(" 译者：",-1)),s(l,{href:"https://github.com/GHLandy"},{default:e(()=>[...t[11]||(t[11]=[i("GHLandy",-1)])]),_:1}),t[15]||(t[15]=i(" 校对：",-1)),s(l,{href:"https://github.com/wxy"},{default:e(()=>[...t[12]||(t[12]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[18]||(t[18]=i("本文由 ",-1)),s(l,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[16]||(t[16]=[i("LCTT",-1)])]),_:1}),t[19]||(t[19]=i(" 原创编译，",-1)),s(l,{href:"https://linux.cn/"},{default:e(()=>[...t[17]||(t[17]=[i("Linux中国",-1)])]),_:1}),t[20]||(t[20]=i(" 荣誉推出",-1))])])}const V=p(m,[["render",d]]);export{C as __pageData,V as default};
